CREATE TABLE IF NOT EXISTS quality_inspections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, inspection_no VARCHAR(100) NOT NULL, purchase_order_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', inspector_id UUID, inspected_at TIMESTAMP WITH TIME ZONE, notes TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_qi_enterprise ON quality_inspections(enterprise_id); CREATE INDEX IF NOT EXISTS idx_qi_po ON quality_inspections(purchase_order_id);
		CREATE TABLE IF NOT EXISTS quality_inspection_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), inspection_id UUID NOT NULL, material_id UUID NOT NULL, check_item VARCHAR(200) NOT NULL, standard VARCHAR(200), result VARCHAR(10) NOT NULL DEFAULT 'pending', fail_reason TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_qii_inspection ON quality_inspection_items(inspection_id);